INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-glass-walkin-closet', 'ตู้เสื้อผ้าบานเฟรมอลูมิเนียมกระจกสีชา (Tinted Glass Walk-in Closet) สวยหรูสไตล์ Luxury Boutique', 'bedroom-living', 'Wardrobe & Dressing / Modern Luxury', 'เปลี่ยนมุมแต่งตัวให้กลายเป็น Walk-in Closet ระดับไฮเอนด์ ด้วยตู้เสื้อผ้าบานกระจกสีชาดำ (Dark Tinted Glass) เสริมกรอบอลูมิเนียม Slim Profile สีดำด้าน พร้อมไฟซ่อน LED แถบแนวตั้งในตู้', '[{"heading":"1. กระจกสีชาดำตัดแสง (Tinted Glass) เพิ่มความลึกลับและเป็นระเบียบ","body":"กระจกสีชาช่วยพรางสายตาจากความไม่เป็นระเบียบของเสื้อผ้าภายในเมื่อปิดไฟ แต่เมื่อเปิดไฟ LED ด้านในตู้ จะมองเห็นคอลเลกชันเสื้อผ้าและกระเป๋าแบรนด์เนมได้อย่างโดดเด่น"},{"heading":"2. กรอบอลูมิเนียม Slim Profile แข็งแรงและไร้สนิม","body":"เฟรมอลูมิเนียมอโนไดซ์เส้นบางเฉียบ ทนต่อความชื้น ไม่บิดงอ รับน้ำหนักบานกระจกนิรภัยเทมเปอร์ (Tempered Glass) ได้อย่างมั่นคงและปลอดภัย"},{"heading":"3. ไฟ LED ซ่อนโปรไฟล์แนวตั้ง (Vertical Integrated LED Strip)","body":"ฝังเส้นไฟ LED ซ่อนเข้ากับขอบเสาตู้โดยตรง ให้แสง Warm White ส่องสว่างทั่วถึงทุกชั้นวาง ไม่แยงตา และช่วยให้เลือกชุดได้สะดวกในทุกช่วงเวลา"}]'::jsonb, '["บานกระจกสีชาเทมเปอร์ตัดแสงพรางสายตา","กรอบอลูมิเนียม Slim Profile ดีไซน์เรียบหรู","ระบบไฟ LED ฝังโปรไฟล์แนวตั้งในตัวตู้"]'::jsonb, '/images/articles/fb-19kU1SK68U.jpg', 'https://www.facebook.com/share/p/19kU1SK68U/', 'อ่าน 3 นาที', '{"#ikammhome","#WalkInCloset","#ตู้เสื้อผ้ากระจกชา","#กระจกสีชาดำ","#SlimProfileGlass","#LuxuryWardrobe"}'::text[], TRUE)
