INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-modern-tv-fluted', 'ดีไซน์ผนังทีวีโมเดิร์นลักชัวรีด้วยแผงระแนงไม้และตู้ลอยซ่อนสายไฟเนียนกริบ', 'bedroom-living', 'Living Room & Entertainment', 'ยกระดับห้องนั่งเล่นให้สวยหรูเหมือนบ้านตัวอย่าง ด้วยงานบิ้วอินผนังทีวีลายหินอ่อนจับคู่ไม้ระแนง ผสานไฟหลืบ LED Warm White และตู้แขวนลอยซ่อนกล่องปลั๊ก-สายไฟ 100%', '[{"heading":"1. ผสมผสานวัสดุหิน ลายไม้ระแนง และเส้นสายคิ้วสแตนเลส","body":"สร้างมิติทางสายตาด้วยแผงลายหินอ่อนขนาดใหญ่ตัดกับไม้ระแนงเซาะร่อง (Fluted Wall Panel) และเสริมความหรูหราด้วยคิ้วสแตนเลสสีทอง Champagne Gold"},{"heading":"2. ตู้วางทีวีแบบแขวนลอย (Floating Console) ซ่อนสายไฟ 100%","body":"ยกตู้ลอยเหนือพื้น 20–25 ซม. เพื่อความโปร่งตาและสะดวกต่อการทำความสะอาดของหุ่นยนต์ดูดฝุ่น พร้อมช่อง Conduit ซ่อนสาย HDMI และปลั๊กไฟในผนัง"},{"heading":"3. แสงไฟหลืบ Cove Light เพิ่มบรรยากาศโรงภาพยนตร์ส่วนตัว","body":"เดินไฟ LED Strip 3000K ซ่อนหลังแผงผนังหินและใต้ตู้แขวนลอย ช่วยปรับเปลี่ยนอารมณ์ห้องนั่งเล่นให้ผ่อนคลายและดูอบอุ่นยามค่ำคืน"}]'::jsonb, '["แผงระแนงเซาะร่องจับคู่ลายหินหรูหรา","ตู้ทีวีแบบลอยตัวซ่อนสายไฟและปลั๊กเรียบร้อย","ไฟซ่อน Cove Light สร้างบรรยากาศผ่อนคลาย"]'::jsonb, '/images/articles/fb-1FQxX6QjKs.jpg', 'https://www.facebook.com/share/p/1FQxX6QjKs/', 'อ่าน 3 นาที', '{"#ikammhome","#ผนังระแนงตกแต่ง","#ตู้ทีวีแขวนลอย","#ซ่อนสายไฟเนียนกริบ","#ModernLuxuryTV"}'::text[], TRUE)
