INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-concealed-door', 'ประตูบานซ่อน (Concealed Door) ให้ผนังบ้านดูเรียบหรูไร้รอยต่อ', 'materials-commercial', 'Product Spotlight / Interior Aesthetics', 'เปลี่ยนประตูห้องนอนหรือห้องน้ำเดิมๆ ให้กลืนไปกับผนังบิ้วอินด้วยประตูบานซ่อน (Concealed Door) ไร้กรอบบัวเกะกะสายตา สร้างเส้นสายผนังที่เรียบหรูไร้รอยต่ออย่างแท้จริง', '[{"heading":"1. บานประตูกลืนไปกับผนังบิ้วอิน (Seamless Wall Integration)","body":"ประตูบานซ่อนถูกออกแบบให้หน้าบานเสมอแนวเดียวกับผนังตกแต่งและปิดผิวด้วยลามิเนต ไม้ระแนง หรือสีเดียวกับผนัง ทำให้ห้องดูต่อเนื่องโปร่งสบายตาและเพิ่มความหรูหราระดับโรงแรม"},{"heading":"2. ไร้คิ้วบัวและวงกบโผล่ (Frameless Architecture)","body":"ใช้วงกบซ่อนในผนังร่วมกับบานพับซ่อนปรับ 3 ทิศทาง (Concealed 3D Hinges) ทำให้เมื่อปิดประตูแล้วจะไม่เห็นบานพับหรือวงกบยื่นออกมาจากแนวผนัง"},{"heading":"3. เหมาะสำหรับประตูห้องนอน ห้องน้ำ และห้องเก็บของ","body":"ช่วยซ่อนประตูห้องน้ำหรือประตูทางเข้าโซนส่วนตัวไม่ให้สะดุดตาในโถงรับแขกหรือห้องนอนใหญ่ พร้อมกลอนแม่เหล็ก (Magnetic Lock) ปิดนุ่มเงียบสนิท"}]'::jsonb, '["หน้าบานเสมอแนวผนังกลืนไปกับงานบิ้วอิน","วงกบและบานพับซ่อน 3 มิติไร้รอยต่อ","เหมาะกับประตูห้องนอน ห้องน้ำ และห้อง Walk-in Closet"]'::jsonb, '/images/articles/concealed-door.jpg', 'https://www.facebook.com/share/p/19dJsrkaMn/', 'อ่าน 3 นาที', '{"#ikammhome","#ConcealedDoor","#ประตูบานซ่อน","#บานประตูกลืนผนัง","#InteriorAesthetics"}'::text[], TRUE)
