INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-fitting-softclose', 'เปิดกรุอุปกรณ์ Fitting บิวท์อินระดับพรีเมียม Soft-Close & Lift-Up', 'materials-commercial', 'Quality & Durability', 'ความแตกต่างของงานบิ้วอินเกรดพรีเมียมอยู่ที่ฟิตติ้งภายใน! พบกับระบบบานพับ รางลิ้นชัก Soft-Close และชุดยกบานตู้บน Lift-Up ที่เปิด-ปิดนุ่มนวล เงียบสนิท และทนทาน', '[{"heading":"1. บานพับและรางลิ้นชัก Soft-Close เงียบสนิท","body":"ระบบโช้กกันกระแทกช่วยชะลอจังหวะปิดหน้าบานและลิ้นชักทุกครั้ง ลดเสียงดังรบกวนและยืดอายุการใช้งานโครงสร้างตู้"},{"heading":"2. ระบบ Lift-Up สำหรับตู้ลอยบานยกขึ้น","body":"ช่วยให้เปิดตู้แขวนด้านบนค้างไว้ในระดับที่ต้องการได้สะดวก ไม่ต้องกลัวศีรษะชนมุมบานตู้ขณะหยิบของ"},{"heading":"3. ทนทานต่อการใช้งานจริงทุกวัน","body":"คัดสรรฟิตติ้งเกรดมาตรฐานยุโรปที่ผ่านการทดสอบการเปิด-ปิดหลายหมื่นรอบเพื่อความคุ้มค่าระยะยาว"}]'::jsonb, '["บานพับและรางลิ้นชัก Soft-Close ปิดนุ่มเงียบ","ชุดฟิตติ้ง Lift-Up เปิดยกค้างได้ทุกองศา","มาตรฐานความทนทานระดับพรีเมียม"]'::jsonb, '/images/articles/fb-1ED8yhf32u.jpg', 'https://www.facebook.com/share/p/1ED8yhf32u/', 'อ่าน 3 นาที', '{"#ikammhome","#SoftClose","#LiftUpFitting","#ฟิตติ้งบิ้วอิน","#QualityDurability"}'::text[], TRUE)
