INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-hmr-vs-plywood', 'บอกลาปัญหาตู้บวมและปลวกกิน ด้วยการเลือกโครงสร้างไม้ที่ถูกต้อง (HMR vs ไม้อัดยาง)', 'materials-commercial', 'Educational / Durability', 'หน้าฝนทีไรตู้บวมทุกที? เจาะลึกการเลือกวัสดุโครงสร้างตู้บิ้วอินระหว่างไม้ HMR ทนความชื้นสูง กับไม้อัดยางคุณภาพสูง เพื่อให้ตู้สวยแข็งแรงไม่บวมพอง', '[{"heading":"1. ไม้ HMR (High Moisture Resistance)","body":"เนื้อไม้ละเอียดอัดแน่นผสมสารกันชื้นสีเขียว ทนความชื้นได้ดีกว่าไม้ปาร์ติเคิลทั่วไป ผิวเรียบสม่ำเสมอ เหมาะกับงานตัด CNC และปิดผิวลามิเนต"},{"heading":"2. ไม้อัดยางคุณภาพสูง (High-Grade Plywood)","body":"โครงสร้างแผ่นไม้ซ้อนหลายชั้น รับน้ำหนักสกรูและบานพับได้ดีมาก แข็งแรงทนทานต่อการยึดเกาะและงานโครงสร้างตู้ใหญ่"},{"heading":"3. เลือกใช้ให้ถูกจุดเพื่ออายุการใช้งานยาวนาน","body":"ทีม iKamm ช่วยแนะนำเกรดไม้ที่เหมาะกับแต่ละโซนของบ้าน ทั้งห้องนอน ห้องนั่งเล่น และโซนที่มีความชื้น"}]'::jsonb, '["ไม้ HMR ผสมสารกันชื้นเนื้อแน่นเรียบเนียน","ไม้อัดยางคุณภาพสูงรับแรงยึดสกรูได้ดีเยี่ยม","เลือกโครงสร้างให้เหมาะกับความชื้นแต่ละโซน"]'::jsonb, '/images/articles/fb-1A9PP53BJi.jpg', 'https://www.facebook.com/share/p/1A9PP53BJi/', 'อ่าน 4 นาที', '{"#ikammhome","#ไม้HMR","#ไม้อัดยาง","#กันชื้น","#MaterialGuide"}'::text[], TRUE)
