INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-onestop-service', 'บิ้วอินทั้งที ทำไมต้องเลือกบริการแบบครบวงจร (One-Stop Service)?', 'brand-safety', 'Brand Trust & Process', 'หมดปัญหางานไม่ตรงปกและช่างทิ้งงาน! ด้วยระบบ One-Stop Service 3 ขั้นตอนมาตรฐานของ iKamm: ออกแบบ 3D -> ผลิตจากโรงงาน -> ติดตั้งโดยช่างมืออาชีพ', '[{"heading":"1. ออกแบบ 3D เสมือนจริงก่อนเริ่มผลิต","body":"เห็นภาพสัดส่วน แสงเงา และโทนสีวัสดุจริงก่อนตัดสินใจ แก้ไขแบบจนมั่นใจก่อนเข้าสายการผลิต"},{"heading":"2. ผลิตจากโรงงานมาตรฐานของตัวเอง","body":"ควบคุมความแม่นยำด้วยเครื่องจักร CNC และระบบ QC ชิ้นงานก่อนขนส่งเข้าหน้างาน"},{"heading":"3. ติดตั้งโดยทีมช่างประจำมืออาชีพ","body":"ทำงานสะอาด เก็บรายละเอียดเรียบร้อย และมีผู้ดูแลโปรเจกต์ติดตามงานจนวันส่งมอบ"}]'::jsonb, '["1. ออกแบบ 3D เสมือนจริงตรงใจ","2. ผลิตด้วยเครื่องจักร CNC จากโรงงาน","3. ติดตั้งโดยช่างประจำ จบครบในที่เดียว"]'::jsonb, '/images/articles/fb-18o3sgrodg.jpg', 'https://www.facebook.com/share/p/18o3sgrodg/', 'อ่าน 3 นาที', '{"#ikammhome","#OneStopService","#บิ้วอินครบวงจร","#ออกแบบ3D","#ส่งมอบตรงเวลา"}'::text[], TRUE)
