INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-dead-space-1', 'เปลี่ยนทุกมุมบอด ให้เป็นมุมโปรดที่ใช้งานได้จริง (ใต้บันได / ซอกหลืบ / เสาหลอก)', 'condo-space', 'Space Optimization / Problem Solving', 'สังเกตไหมว่าในบ้านมี "มุมบอด" ที่ทิ้งว่างไว้กี่จุด? ทั้งมุมใต้บันได ซอกหลืบข้างตู้ หรือเสาหลอก สามารถออกแบบบิ้วอินให้กลายเป็นพื้นที่จัดเก็บสุดคุ้มได้', '[{"heading":"1. พื้นที่ใต้บันไดกลายเป็นตู้และลิ้นชักความจุสูง","body":"สั่งตัดตู้และลิ้นชักสไลด์ทรงเฉียงแนบแนวบันได เพื่อเก็บรองเท้า กระเป๋า และของใช้ในบ้าน"},{"heading":"2. ซอกหลืบและช่องว่างข้างเสา","body":"เปลี่ยนซอกแคบข้างเสาโครงสร้างให้เป็นตู้โชว์ ชั้นวางหนังสือ หรือตู้บิ้วอินหน้าแคบแบบดึงออกได้"},{"heading":"3. ปรับความลึกเฉพาะจุดตามหน้างานจริง","body":"งานสั่งผลิตบิ้วอินช่วยให้ปรับขนาดมิลลิเมตรต่อมิลลิเมตร ต่างจากเฟอร์นิเจอร์ลอยตัวที่เหลือช่องว่างเก็บฝุ่น"}]'::jsonb, '["แปลงมุมใต้บันได ซอกหลืบ และเสาหลอกให้ใช้งานได้","สั่งผลิตพอดีพื้นที่จริง ลดช่องว่างสะสมฝุ่น","เพิ่มพื้นที่จัดเก็บในบ้านโดยไม่กินพื้นที่ทางเดิน"]'::jsonb, '/images/articles/fb-1EquWr4cr7.jpg', 'https://www.facebook.com/share/p/1EquWr4cr7/', 'อ่าน 3 นาที', '{"#ikammhome","#SpaceOptimization","#เปลี่ยนมุมบอด","#เก็บของใต้บันได","#มุมโปรด"}'::text[], TRUE)
