INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-kitchen-countertops', 'เจาะลึก 3 วัสดุท็อปครัวยอดนิยม สวย ทน ไม่กลัวพัง! (แกรนิต vs หินสังเคราะห์ vs เซรามิก)', 'kitchen-bar', 'Educational / Material Guide', 'เลือกท็อปเคาน์เตอร์ครัวอย่าดูแค่สวย! เปรียบเทียบจุดเด่นของ หินแกรนิต, หินสังเคราะห์ (Quartz/Solid Surface), และเซรามิกแผ่นใหญ่ (Sintered Stone) เพื่อเลือกให้ตรงสไตล์การทำครัว', '[{"heading":"1. หินแกรนิตธรรมชาติ (Granite)","body":"แข็งแกร่งมาก ทนความร้อนและแรงสับโขลกได้ดี เหมาะกับครัวไทยทำอาหารหนักเป็นประจำ"},{"heading":"2. หินสังเคราะห์ (Engineered Quartz / Solid Surface)","body":"ลวดลายสม่ำเสมอ รูพรุนน้อย ลดคราบซึมจากกาแฟและซอส สีขาวลายหินอ่อนดูโมเดิร์นสะอาดตา"},{"heading":"3. เซรามิกแผ่นใหญ่ / หินเผา (Sintered Stone)","body":"ทนความร้อนสูงและทนรอยขีดข่วนดีเยี่ยม สามารถวางหม้อร้อนหรือหั่นเบาๆ บนผิวได้โดยไม่ทิ้งรอย"}]'::jsonb, '["หินแกรนิต: แกร่งทนแรงสับโขลก เหมาะกับครัวไทย","หินสังเคราะห์: ผิวเนียนไร้รูพรุน ลายหินอ่อนสวย","เซรามิกแผ่นใหญ่: ทนความร้อนสูงและกันรอยขีดข่วนเยี่ยม"]'::jsonb, '/images/articles/fb-1HwgYUYUQa.jpg', 'https://www.facebook.com/share/p/1HwgYUYUQa/', 'อ่าน 4 นาที', '{"#ikammhome","#ท็อปครัว","#หินแกรนิต","#หินสังเคราะห์","#เซรามิกแผ่นใหญ่"}'::text[], TRUE)
