INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-dead-space-2', 'เบื่อไหม? มุมเสาและพื้นที่ใต้บันไดที่ปล่อยทิ้งไว้เฉยๆ เปลี่ยนเป็นมุมโปรดได้!', 'condo-space', 'Space Optimization / Problem Solving', 'เปลี่ยนมุมเสาที่ยื่นเกะกะและพื้นที่ว่างใต้บันไดให้ดูสมดุลและใช้สอยได้จริง ด้วยการบิ้วอินหุ้มเสาเชื่อมเป็นตู้โชว์ โต๊ะทำงานขนาดกะทัดรัด หรือตู้เก็บของ', '[{"heading":"1. หุ้มมุมเสาให้กลายเป็นส่วนหนึ่งของตู้บิ้วอิน","body":"ดีไซน์หน้าบานหรือชั้นวางเชื่อมต่อระหว่างเสาและผนัง ทำให้แนวผนังดูเรียบเสมอกันและได้พื้นที่วางของเพิ่ม"},{"heading":"2. มุมทำงานหรือมุมนั่งอ่านหนังสือใต้บันได","body":"สำหรับบ้านทาวน์โฮมหรือบ้านเดี่ยว สามารถบิ้วอินโต๊ะทำงานขนาดพอดีช่องใต้บันไดพร้อมไฟส่องสว่างและปลั๊กไฟครบชุด"},{"heading":"3. เพิ่มความสว่างให้มุมอับดูโปร่งขึ้น","body":"เสริมไฟ LED เส้นใต้ชั้นวางช่วยขับบรรยากาศให้มุมที่เคยมืดทึบกลายเป็นจุดเด่นของบ้าน"}]'::jsonb, '["กลบเหลี่ยมเสาโครงสร้างให้เรียบเนียนเป็นตู้สวย","สร้างมุมโต๊ะทำงานหรือตู้เก็บของใต้บันได","เพิ่มไฟ LED ซ่อนขับบรรยากาศมุมโปรด"]'::jsonb, '/images/articles/fb-1A25JHwZt3.jpg', 'https://www.facebook.com/share/p/1A25JHwZt3/', 'อ่าน 3 นาที', '{"#ikammhome","#มุมเสา","#พื้นที่ใต้บันได","#บิ้วอินแก้ปัญหา","#HomeDesign"}'::text[], TRUE)
