INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-premium-living', 'รังสรรค์พื้นที่ชีวิต ให้เป็นมากกว่าแค่อยู่อาศัย ด้วยงานบิวต์อินระดับพรีเมียมจาก IKAMM HOME DECOR', 'brand-safety', 'Brand Showcase / Full-Home Built-in', 'บ้านไม่ใช่แค่สถานที่ แต่มืออาชีพคือผู้เติมเต็มความหมายของคำว่า "บ้าน" ให้สมบูรณ์แบบ พบกับมาตรฐานการออกแบบและตกแต่งภายในครบวงจรจาก IKAMM HOME DECOR', '[{"heading":"1. ออกแบบเฉพาะตัวให้สะท้อนไลฟ์สไตล์เจ้าของบ้าน","body":"วางผังและเลือกโทนสีวัสดุที่สอดคล้องกับพฤติกรรมการใช้ชีวิตของสมาชิกทุกคนในครอบครัว"},{"heading":"2. คุมงานตั้งแต่งานโครงสร้างบิ้วอินจนถึงดีเทลตกแต่ง","body":"เก็บรายละเอียดขอบคิ้ว ไฟหลืบ หน้าบาน และฟิตติ้งทุกจุดด้วยความประณีตระดับพรีเมียม"},{"heading":"3. พร้อมดูแลให้คำปรึกษาและออกแบบ 3D ครบวงจร","body":"รองรับทั้งบ้านเดี่ยว ทาวน์โฮม คอนโดมิเนียม และโครงการพาณิชย์ในไทยและต่างประเทศ"}]'::jsonb, '["ดีไซน์เฉพาะตัวสะท้อนรสนิยมและไลฟ์สไตล์","งานฝีมือประณีตตั้งแต่โครงสร้างถึงดีเทลตกแต่ง","บริการครบวงจรสำหรับบ้าน คอนโด และธุรกิจ"]'::jsonb, '/images/articles/fb-1FQ4JFfJAv.jpg', 'https://www.facebook.com/share/p/1FQ4JFfJAv/', 'อ่าน 3 นาที', '{"#ikammhome","#IKAMMHOMEDECOR","#งานบิวต์อินระดับพรีเมียม","#บ้านในฝัน"}'::text[], TRUE)
