INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-fb-wood-structure', 'บอกลาปัญหาบิวท์อินบวมน้ำและปลวกกิน ด้วยการเลือก "โครงสร้างไม้" ที่ถูกต้อง', 'materials-commercial', 'Material Durability / Moisture & Termite Protection', 'ทำบิวท์อินทั้งทีไม่อยากปวดหัวเรื่องปลวกหรือไม้บวมน้ำในอนาคต! เรียนรู้การเลือกโครงสร้างไม้และวัสดุกันชื้นที่เหมาะกับสภาพอากาศร้อนชื้นของประเทศไทย', '[{"heading":"1. ทำไมไม้ปาร์ติเคิลธรรมดาจึงบวมน้ำง่าย?","body":"ไม้ปาร์ติเคิลทั่วไปมีช่องว่างระหว่างเนื้อไม้มาก เมื่อโดนความชื้นหรือซึมน้ำตามขอบปิดผิวจะพองตัวและเสื่อมสภาพเร็ว"},{"heading":"2. อัปเกรดเป็นไม้ HMR, ไม้อัดยางเกรดสูง หรือ Plaswood","body":"เลือกใช้ไม้ HMR สำหรับงานตู้ภายในทั่วไป ไม้อัดยางสำหรับงานรับน้ำหนัก และ Plaswood กันน้ำ 100% สำหรับโซนซิงก์ล้างจานหรือห้องน้ำ"},{"heading":"3. ปิดขอบด้วยเครื่องจักรและกาวกันชื้นมาตรฐานโรงงาน","body":"การปิดขอบ PVC Edge Banding อย่างแนบสนิททุกด้านช่วยป้องกันความชื้นและแมลงเข้าสู่เนื้อไม้"}]'::jsonb, '["หลีกเลี่ยงไม้ปาร์ติเคิลทั่วไปในจุดเสี่ยงชื้น","เลือกใช้ HMR, ไม้อัดยาง หรือ Plaswood ตามโซน","ปิดขอบด้วยเครื่องจักรโรงงานป้องกันความชื้นและปลวก"]'::jsonb, '/images/articles/fb-1EUvb14yPa.jpg', 'https://www.facebook.com/share/p/1EUvb14yPa/', 'อ่าน 4 นาที', '{"#ikammhome","#โครงสร้างไม้","#กันน้ำกันปลวก","#บิ้วอินทนทาน","#MaterialStandard"}'::text[], TRUE)
