INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-02', 'สมาร์ทบิวท์อิน (Smart Home Built-in) ผสานเทคโนโลยีเข้ากับเฟอร์นิเจอร์', 'smart-tech', 'Innovation & Smart Home', 'ยกระดับบ้านยุคใหม่ด้วยการรวมระบบ Smart Switch คุมไฟผ่านแอปและเสียง แท่นชาร์จไร้สายซ่อนใต้ท็อปโต๊ะ และปลั๊กไฟแบบ Pop-up ให้กลมกลืนไปกับงานไม้บิ้วอิน', '[{"heading":"1. ควบคุมแสงสว่างผ่านสมาร์ตโฟนและคำสั่งเสียง","body":"ฝังสวิตช์อัจฉริยะ (Smart Switch) ร่วมกับไฟ LED ในตู้โชว์ ตู้เสื้อผ้า และไฟหลืบหัวเตียง ตั้งเวลาเปิด-ปิดหรือปรับความสว่างได้จากทุกที่"},{"heading":"2. แท่นชาร์จไร้สายซ่อนฝัง (Invisible Wireless Charger)","body":"ติดตั้งคอยล์ชาร์จไร้สายไว้ใต้แผ่นท็อปโต๊ะทำงานหรือโต๊ะข้างเตียง เพียงวางสมาร์ตโฟนลงบนจุดที่กำหนดก็ชาร์จได้ทันทีโดยไม่มีสายไฟเกะกะ"},{"heading":"3. ลิ้นชักไฟฟ้าและปลั๊ก Pop-up เรียบหรู","body":"เสริมความล้ำสมัยด้วยลิ้นชักระบบสัมผัสไฟฟ้า (Touch-to-Open) และชุดปลั๊ก Pop-up ซ่อนตัวบนเคาน์เตอร์ครัวหรือโต๊ะประชุม"}]'::jsonb, '["Smart Switch คุมไฟตู้โชว์ผ่านมือถือ/เสียง","Wireless Charger ซ่อนฝังใต้ท็อปโต๊ะ","ปลั๊ก Pop-up และลิ้นชักระบบสัมผัสไฟฟ้า"]'::jsonb, '/images/articles/smart-builtin.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#SmartHome","#สมาร์ทบิ้วอิน","#เฟอร์นิเจอร์อัจฉริยะ","#InteriorDesign"}'::text[], FALSE)
