INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-03', 'เลือกบานประตูตู้เสื้อผ้า: บานเปิด (Hinged) หรือ บานเลื่อน (Sliding) ดีกว่ากัน?', 'bedroom-living', 'Wardrobe Selection Guide', 'เปรียบเทียบข้อดี-ข้อจำกัดของหน้าบานตู้เสื้อผ้าทั้ง 2 แบบ ทั้งด้านระยะทางเดินหน้าตู้ การมองเห็นเสื้อผ้าทั้งหมด ความทนทานของฟิตติ้ง และความเหมาะสมกับขนาดห้องนอน', '[{"heading":"1. ตู้เสื้อผ้าบานเปิด (Hinged Door)","body":"ข้อดีคือสามารถเปิดบานประตูดูเสื้อผ้าทุกช่องพร้อมกันได้ทั้งหมด และติดตั้งอุปกรณ์เสริมด้านหลังบานประตูได้ แตต้องเว้นระยะทางเดินหน้าตู้อย่างน้อย 60–80 ซม. เพื่อเผื่อวงสวิงเปิด"},{"heading":"2. ตู้เสื้อผ้าบานเลื่อน (Sliding Door)","body":"ตอบโจทย์ห้องนอนขนาดกะทัดรัดหรือพื้นที่ปลายเตียงที่ทางเดินแคบ เพราะไม่กินระยะเปิดหน้าตู้ แต่จะเปิดใช้งานได้ทีละฝั่ง และรางเลื่อนต้องรับน้ำหนักบานได้ดีด้วยระบบ Soft-Close"},{"heading":"3. วิธีเลือกให้ตรงแปลนห้องจริง","body":"หากทางเดินหน้าตู้กว้างเกิน 90 ซม. แนะนำบานเปิดหรือบานกระจกกรอบอะลูมิเนียม แต่ถ้าระยะทางเดินน้อยกว่า 75 ซม. บานเลื่อนรางบนแบบซ่อนรางล่างจะใช้งานคล่องตัวกว่า"}]'::jsonb, '["บานเปิด: มองเห็นเสื้อผ้าครบทุกช่องในครั้งเดียว","บานเลื่อน: ประหยัดระยะสวิง เหมาะกับทางเดินแคบ","ฟิตติ้ง Soft-Close ลดแรงกระแทกทั้งสองระบบ"]'::jsonb, '/images/articles/wardrobe-doors.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#ตู้เสื้อผ้าบานเลื่อน","#ตู้เสื้อผ้าบานเปิด","#จัดห้องนอน","#BuiltinIdeas"}'::text[], FALSE)
