INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-04', 'ตู้เก็บรองเท้าแบบดึงหมุน 360 องศา จุรองเท้าเพิ่มได้ถึง 40 คู่!', 'materials-commercial', 'Hardware Innovation / Entryway', 'แก้ปัญหาตู้รองเท้าล้นทางเข้าบ้านด้วยชุดฟิตติ้งโครงหมุน 360 องศา ใช้หน้ากว้างตู้เพียง 80 ซม. แต่จัดเก็บรองเท้าได้เป็นระเบียบมากถึง 36–40 คู่ หยิบง่ายทั้งสองด้าน', '[{"heading":"1. เพิ่มความจุ 2 เท่าในพื้นที่หน้ากว้างเท่าเดิม","body":"โครงเหล็กหมุน 360 องศาช่วยใช้ความลึกของตู้ได้อย่างเต็มประสิทธิภาพ รองรับชั้นวางปรับระยะได้ทั้งรองเท้าผ้าใบ ส้นสูง และรองเท้าหนัง"},{"heading":"2. ดึง-หมุนลื่นไหล มองเห็นทุกคู่ในพริบตา","body":"หมดปัญหารองเท้าคู่โปรดซ่อนอยู่แถวหลัง เพียงเปิดหน้าบานแล้วหมุนโครงตะแกรง ก็มองเห็นรองเท้าทั้งฝั่งหน้าและฝั่งหลังได้ทันที"},{"heading":"3. ระบายอากาศดี ลดกลิ่นอับหน้าบ้าน","body":"ชั้นวางแบบตะแกรงโปร่งช่วยให้อากาศถ่ายเทได้ดีกว่าชั้นไม้ทึบ ลดการสะสมความชื้นและกลิ่นอับในตู้เก็บรองเท้า"}]'::jsonb, '["โครงเหล็กหมุน 360 องศา หยิบใช้ได้ทั้งสองฝั่ง","หน้าตู้กว้างเพียง 80 ซม. จุสูงสุด 36–40 คู่","ระบายอากาศดี ลดกลิ่นอับและจัดทรงรองเท้าเป็นระเบียบ"]'::jsonb, '/images/articles/shoe-cabinet.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ตู้รองเท้า360องศา","#ฟิตติ้งตู้รองเท้า","#คอนโดคนของเยอะ","#SmartStorage"}'::text[], FALSE)
