INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-05', 'ตกแต่งผนังหัวเตียง (Bed Headboard Wall) เพิ่มความหรูหราแบบโรงแรม 6 ดาว', 'bedroom-living', 'Bedroom Styling / Accent Wall', 'สร้างจุดโฟกัสให้ห้องนอนด้วยผนังหัวเตียงดีไซน์ Material Mix ผสานผ้าบุนวม หนังเทียม ลามิเนตลายหิน คิ้วสแตนเลส Rose Gold และไฟอ่านหนังสือแยกสวิตช์ซ้าย-ขวา', '[{"heading":"1. เทคนิค Material Mix เพิ่มมิติให้ผนังห้องนอน","body":"จับคู่แผ่นบุนวมหัวเตียงนุ่มสบายหลัง กับลามิเนตลายหินอ่อนและไม้ระแนงแนวตั้ง ช่วยสร้างสัมผัสที่หลากหลายและดูมีระดับแบบโรงแรมหกดาว"},{"heading":"2. คิ้วสแตนเลสสีทอง / Rose Gold เสริมความประณีต","body":"เซาะร่องฝังเส้นคิ้วสแตนเลสเกรด 304 ตัดแบ่งจังหวะผนังอย่างสมมาตร สะท้อนแสงไฟในห้องนอนให้ดูอบอุ่นหรูหรา"},{"heading":"3. ระบบไฟหัวเตียงและปลั๊กไฟซ้าย-ขวาครบครัน","body":"ออกแบบไฟหลืบ Indirect Light หลังแผ่นหัวเตียง พร้อมโคมไฟอ่านหนังสือและจุดปลั๊กไฟ/USB แยกอิสระทั้งสองฝั่งเตียง"}]'::jsonb, '["Material Mix: ผ้าบุนวม หนังเทียม ลามิเนตลายหิน","คิ้วสแตนเลส Rose Gold และระแนงไม้ตกแต่ง","ไฟอ่านหนังสือและสวิตช์แยกอิสระซ้าย-ขวา"]'::jsonb, '/images/articles/headboard-wall.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#ผนังหัวเตียง","#HeadboardDesign","#แต่งห้องนอนหรู","#ModernLuxury"}'::text[], FALSE)
