INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-06', 'บิ้วอินคลินิก ร้านค้า และออฟฟิศสำนักงาน เพิ่มภาพลักษณ์น่าเชื่อถือและดึงดูดลูกค้า', 'materials-commercial', 'Commercial & Office Built-in', 'บริการออกแบบและผลิตเฟอร์นิเจอร์บิ้วอินเชิงพาณิชย์สำหรับคลินิกความงาม สปา ร้านยา และออฟฟิศ ด้วยวัสดุเกรดทนทานพิเศษพร้อมเคาน์เตอร์ต้อนรับที่สะท้อนตัวตนแบรนด์', '[{"heading":"1. เคาน์เตอร์ Reception จุดสร้างความประทับใจแรก","body":"ออกแบบเคาน์เตอร์ต้อนรับทรงโค้งหรือโมเดิร์นกรุระแนงไม้-ลายหิน พร้อมไฟส่องโลโก้แบรนด์และลิ้นชักเก็บเอกสารซ่อนมิดชิดด้านใน"},{"heading":"2. ตู้โชว์สินค้าและห้องประชุมฟังก์ชันครบ","body":"ติดตั้งตู้โชว์กระจกพร้อมไฟ Spotlight สำหรับคลินิกและร้านค้า รวมถึงโต๊ะประชุมบิ้วอินซ่อนรางสายไฟและงานห้องผู้บริหาร"},{"heading":"3. วัสดุ Commercial Grade ทนทานทำความสะอาดง่าย","body":"คัดสรรลามิเนตทนรอยขีดข่วนและบอร์ดกันชื้นรองรับการเช็ดทำความสะอาดด้วยน้ำยาฆ่าเชื้อทุกวัน"}]'::jsonb, '["เคาน์เตอร์ Reception เสริมภาพลักษณ์ธุรกิจ","ตู้โชว์สินค้าและห้องประชุมครบวงจร","วัสดุเกรดพาณิชย์ทนทาน เช็ดทำความสะอาดง่าย"]'::jsonb, '/images/articles/commercial-reception.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#บิ้วอินออฟฟิศ","#เคาน์เตอร์ต้อนรับ","#บิ้วอินคลินิก","#งานพาณิชย์"}'::text[], FALSE)
