INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-07', 'แก้ปัญหาปลั๊กไฟไม่พอ ด้วยรางปลั๊กระบบแทร็ก (Power Track) ฝังบนเฟอร์นิเจอร์', 'smart-tech', 'Smart Living / Electrical', 'บอกลาปลั๊กพ่วงและสายไฟพันกัน ด้วยรางปลั๊กไฟอะลูมิเนียม Power Track ฝังเรียบไปกับเคาน์เตอร์ครัวหรือโต๊ะทำงาน เพิ่ม-ลดและเลื่อนหัวปลั๊กได้อิสระ', '[{"heading":"1. เลื่อนปรับตำแหน่งและเพิ่มหัวปลั๊กได้ตลอดเวลา","body":"ราง Power Track รองรับทั้งหัวปลั๊กมาตรฐาน มอก. และหัวชาร์จ USB-A / USB-C แบบบิดล็อก ถอดย้ายตำแหน่งบนรางได้ภายใน 1 วินาที"},{"heading":"2. ฝังเนียนบนหน้าท็อปโต๊ะทำงานและผนังครัว","body":"สามารถติดตั้งแบบฝังเสมอผิว (Flush Mount) บนท็อปไม้ เคาน์เตอร์หิน หรือผนังกันเปื้อนหลังเคาน์เตอร์ครัว"},{"heading":"3. ระบบป้องกันไฟดูดและฝุ่นละอองปลอดภัยสูง","body":"รางออกแบบช่องสัมผัสแบบแคบและมีฉนวนป้องกันนิ้วสัมผัส พร้อมระบบตัดไฟมาตรฐานเพื่อความปลอดภัยในบ้าน"}]'::jsonb, '["ราง Power Track อะลูมิเนียมฝังเรียบสนิท","เพิ่ม-ย้ายหัวปลั๊กไฟและ USB-C ได้อิสระ","ปลอดภัยจากฝุ่นและลดสายไฟพาดระโยงระยาง"]'::jsonb, '/images/articles/power-track.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#PowerTrack","#รางปลั๊กไฟ","#บิ้วอินโต๊ะทำงาน","#SmartLiving"}'::text[], FALSE)
