INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-08', 'เคาน์เตอร์บาร์ในบ้าน (Mini Home Bar) จุดพักผ่อนสุดชิลหลังเลิกงาน', 'kitchen-bar', 'Lifestyle / Entertaining', 'เนรมิตมุมสังสรรค์และจิบเครื่องดื่มในบ้านด้วยเคาน์เตอร์ Mini Bar เชื่อมระหว่างห้องนั่งเล่นและครัว พร้อมท็อปหินสังเคราะห์ ราวแขวนแก้วสแตนเลส และไฟส่องสว่างสร้างมู้ด', '[{"heading":"1. เชื่อมพื้นที่ Pantry และ Living Room อย่างลงตัว","body":"เคาน์เตอร์บาร์ขนาดกะทัดรัดกว้าง 45–60 ซม. สูง 105–110 ซม. ช่วยแบ่งโซนเบาๆ โดยยังพูดคุยกับคนในห้องนั่งเล่นได้"},{"heading":"2. ราวแขวนแก้วไวน์และช่องเก็บขวดเครื่องดื่ม","body":"ออกแบบตู้ลอยด้านบนสำหรับแขวนแก้วไวน์สแตนเลส ช่องวางเครื่องชงกาแฟ และช่องแช่ไวน์ขนาดเล็กด้านล่าง"},{"heading":"3. แสงไฟ Warm Ambient สร้างบรรยากาศผ่อนคลาย","body":"ติดตั้งไฟหลืบส่องชั้นวางเครื่องดื่มและไฟใต้เคาน์เตอร์ ให้ความรู้สึกอบอุ่นเหมือนบาร์ส่วนตัวระดับพรีเมียม"}]'::jsonb, '["ท็อปหินสังเคราะห์ทนรอยและคราบเครื่องดื่ม","ราวแขวนแก้วไวน์และช่องวาง Wine Chiller","ไฟส่องสว่าง Warm Ambient สร้างมู้ดยามค่ำ"]'::jsonb, '/images/articles/kitchen-ergonomic.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#เคาน์เตอร์บาร์","#MiniBar","#มุมพักผ่อนในบ้าน","#Lifestyle"}'::text[], FALSE)
