INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-09', '3 ข้อผิดพลาดของการทำครัว ที่คนส่วนใหญ่มาเสียใจทีหลัง!', 'kitchen-bar', 'Pain Point & Warning Tips', 'เช็กลิสต์ 3 จุดพลาดยอดฮิตก่อนสั่งทำครัวบิ้วอิน ทั้งการลืมเผื่อขนาดเครื่องใช้ไฟฟ้า ปลั๊กไฟไม่พอ และระยะเปิดหน้าบานชนกัน พร้อมแนวทางป้องกันจากทีม iKamm', '[{"heading":"ข้อผิดพลาดที่ 1: ลืมคำนวณขนาดเครื่องใช้ไฟฟ้าล่วงหน้า","body":"หลายคนซื้อหม้อทอดไร้น้ำมัน เตาอบ หรือตู้เย็น 2 ประตูทีหลัง ทำให้ช่องบิ้วอินแคบเกินไปหรือไม่มีช่องระบายความร้อนด้านหลัง"},{"heading":"ข้อผิดพลาดที่ 2: ปลั๊กไฟน้อยเกินไปและวางผิดจุด","body":"มุมเตรียมอาหารมักต้องใช้เครื่องปั่น กาน้ำร้อน และหม้อหุงข้าวพร้อมกัน ควรแยกเบรกเกอร์และวางตำแหน่งปลั๊กเหนือเคาน์เตอร์ให้เพียงพอ"},{"heading":"ข้อผิดพลาดที่ 3: เว้นทางเดินแคบและหน้าบานชนกัน","body":"ระยะทางเดินระหว่างเคาน์เตอร์ควรอย่างน้อย 90–110 ซม. เพื่อให้เปิดประตูตู้เย็นหรือเครื่องล้างจานได้โดยไม่ชนหน้าบานฝั่งตรงข้าม"}]'::jsonb, '["วางสเปกช่องเครื่องใช้ไฟฟ้าและระยะระบายความร้อนก่อนผลิต","ออกแบบจุดปลั๊กไฟเฉพาะสำหรับเครื่องใช้ไฟฟ้ากำลังสูง","ตรวจระยะทางเดิน 90–110 ซม. ไม่ให้หน้าบานชนกัน"]'::jsonb, '/images/articles/stainless-trim.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#ข้อผิดพลาดแต่งครัว","#ครัวไทย","#ทำครัวไม่อึดอัด","#KitchenDesign"}'::text[], FALSE)
