INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-10', 'การเลือกคิ้วตกแต่งสแตนเลส (Stainless Trim) เพื่อเพิ่มความเรียบหรูระดับลักชัวรี', 'materials-commercial', 'Finishing Details / Luxury', 'เส้นสายโลหะเล็กๆ ที่ยกระดับงานบิ้วอินธรรมดาให้ดูหรูหราแบบ Modern Luxury ด้วยคิ้วสแตนเลสเกรด 304 สี Gold, Rose Gold และ Black Mirror', '[{"heading":"1. ต้องเลือกสแตนเลสเกรด 304 แท้เท่านั้น","body":"คิ้วสแตนเลสเกรด 304 ทนความชื้น ไม่ขึ้นสนิม และผิวเคลือบ PVD สีไม่ลอกร่อน เหมาะกับงานตกแต่งภายในระยะยาว"},{"heading":"2. จับคู่สีคิ้วให้เข้ากับสไตล์และหน้าบาน","body":"สี Gold / Rose Gold เข้าได้ดีกับหน้าบานลายหินอ่อนสีขาวและไม้โอ๊ค ส่วนสี Black Mirror เหมาะกับสไตล์โมเดิร์นดาร์กและสีเทาเข้ม"},{"heading":"3. งานเซาะร่องฝังคิ้วเรียบเสมอผิว (Flush Inlay)","body":"ใช้เครื่อง CNC เซาะร่องหน้าบานและผนังให้ได้ความลึกพอดี ทำให้คิ้วฝังเรียบเนียนไม่สะดุดมือและไม่เก็บฝุ่น"}]'::jsonb, '["สแตนเลสเกรด 304 เคลือบ PVD ไม่เป็นสนิม","มีสี Gold, Rose Gold และ Black Mirror","เซาะร่อง CNC ฝังเรียบเสมอผิวหน้าบาน"]'::jsonb, '/images/articles/stainless-trim.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#คิ้วสแตนเลส","#ModernLuxury","#ดีเทลแต่งบ้าน","#StainlessTrim"}'::text[], FALSE)
