INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-11', 'ตู้เก็บกระเป๋าเดินทางและของชิ้นใหญ่ ซ่อนอย่างเนียนตาไม่รกบ้าน', 'condo-space', 'Bulky Storage / Living Organization', 'แก้ปัญหาสัมภาระชิ้นใหญ่อย่างกระเป๋าเดินทาง 28 นิ้ว บันไดพับ และกล่องอุปกรณ์ ด้วยตู้สูงบิ้วอินชนเพดานที่ออกแบบช่องไร้คานกั้นตายตัว', '[{"heading":"1. ออกแบบความลึก 60–65 ซม. รองรับกระเป๋าเดินทาง","body":"ตู้เก็บของทั่วไปมักลึกเพียง 35–40 ซม. จึงวางกระเป๋าเดินทางใบใหญ่ไม่ได้ การกำหนดความลึก 60–65 ซม. ช่วยให้เก็บกระเป๋า 24–28 นิ้วได้มิดชิด"},{"heading":"2. ชั้นวางปรับระดับได้และโซนแนวตั้ง","body":"แบ่งฝั่งหนึ่งเป็นช่องสูงไร้ชั้นกั้นสำหรับบันไดช่างและเครื่องดูดฝุ่น อีกฝั่งเป็นชั้นปรับระดับรองรับน้ำหนักกระเป๋าและกล่องพลาสติก"},{"heading":"3. หน้าบานเรียบกลืนไปกับผนังบ้าน","body":"ใช้หน้าบานเปิดระบบกดกระเด้ง (Push-to-Open) หรือมือจับซ่อน เมื่อปิดตู้แล้วดูเรียบเนียนเหมือนผนังตกแต่ง"}]'::jsonb, '["ความลึก 60–65 ซม. เก็บกระเป๋าเดินทาง 28 นิ้วได้จริง","แบ่งช่องแนวตั้งสูงสำหรับบันไดและเครื่องดูดฝุ่น","หน้าบาน Push-to-Open เรียบเนียนกลืนไปกับผนัง"]'::jsonb, '/images/articles/wardrobe-doors.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ตู้เก็บของชิ้นใหญ่","#จัดบ้านรก","#บิ้วอินตู้สูง","#SpaceSaving"}'::text[], FALSE)
