INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-12', 'มุมโต๊ะเครื่องแป้งในตู้เสื้อผ้า (Integrated Vanity) ฟังก์ชัน 2-in-1 ในห้องนอน', 'condo-space', 'Space Saving / Bedroom', 'ประหยัดพื้นที่ผนังห้องนอนด้วยการออกแบบโต๊ะเครื่องแป้งฝังรวมเป็นแนวเดียวกับตู้เสื้อผ้า สวยกลมกลืน ใช้งานแต่งตัวและจัดเก็บเครื่องสำอางได้ครบในจุดเดียว', '[{"heading":"1. รวม 2 ฟังก์ชันไว้ในผนังเดียว","body":"แทนที่จะแยกตั้งโต๊ะแป้งต่างหากซึ่งกินพื้นที่ทางเดิน การฝังโต๊ะแป้งไว้กึ่งกลางหรือริมสุดของตู้เสื้อผ้าช่วยให้แนวผนังดูต่อเนื่องสะอาดตา"},{"heading":"2. ลิ้นชักตื้นแบ่งช่องเก็บเครื่องประดับและสกินแคร์","body":"ออกแบบลิ้นชักบนท็อปโต๊ะแป้งพร้อมถาดกำมะหยี่แบ่งช่อง สำหรับเก็บนาฬิกา แหวน แว่นตา และลิปสติกเป็นระเบียบ"},{"heading":"3. ตู้ลอยด้านบนและกระจกไฟ LED","body":"พื้นที่เหนือกระจกเงายังสามารถทำเป็นตู้ลอยเก็บของเพิ่มเติมได้ พร้อมติดไฟ LED รอบกระจกให้แต่งหน้าได้ชัดเจน"}]'::jsonb, '["ผสานโต๊ะเครื่องแป้งเป็นแนวเดียวกับตู้เสื้อผ้า","ลิ้นชักแบ่งช่องเก็บเครื่องประดับและเครื่องสำอาง","กระจกติดไฟ LED พร้อมตู้เก็บของด้านบน"]'::jsonb, '/images/articles/smart-mirror.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ตู้เสื้อผ้าพร้อมโต๊ะแป้ง","#IntegratedVanity","#แต่งห้องนอนขนาดเล็ก","#BedroomIdeas"}'::text[], FALSE)
