INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-13', 'บิ้วอินทนชื้นสำหรับห้องซักล้างกึ่งเอาต์ดอร์ (Semi-Outdoor Laundry)', 'kitchen-bar', 'Durability / Outdoor Material', 'หมดกังวลเรื่องตู้บวมน้ำและปลวกกินในโซนซักล้างหลังบ้าน ด้วยวัสดุโครงสร้างพลาสวูด (Plaswood) กันน้ำ 100% จับคู่หน้าท็อปหินแกรนิตทนแดดทนฝน', '[{"heading":"1. โครงสร้าง Plaswood กันน้ำ 100% ปลอดปลวก","body":"สำหรับพื้นที่กึ่งภายนอกหรือใกล้จุดต่อน้ำเครื่องซักผ้า ไม้ปาร์ติเคิลทั่วไปจะบวมพองได้ง่าย การใช้แผ่นพลาสวูดความหนาแน่นสูงจึงทนความชื้นได้ตลอดอายุการใช้งาน"},{"heading":"2. ท็อปหินแกรนิตธรรมชาติทนทุกสภาพอากาศ","body":"หน้าท็อปหินแกรนิตทนทั้งความร้อนจากแสงแดด น้ำยาซักผ้า และแรงกระแทกจากการวางตะกร้าผ้าหนักๆ"},{"heading":"3. จัดระเบียบเครื่องซัก-อบผ้าและอ่างซักล้าง","body":"เว้นช่องวางเครื่องซักผ้าและเครื่องอบผ้าแบบเคียงข้างกัน พร้อมตู้แขวนเก็บผงซักฟอกและราวแขวนผ้าพับเก็บได้"}]'::jsonb, '["โครงสร้างพลาสวูด (Plaswood) กันน้ำ 100%","หน้าท็อปหินแกรนิตทนแดด ทนความชื้น","ออกแบบช่องวางเครื่องซัก-อบผ้าและซิงก์เฉพาะจุด"]'::jsonb, '/images/articles/balcony-lounge.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#บิ้วอินกันน้ำ","#เคาน์เตอร์ซักล้าง","#วัสดุทนฝน","#Plaswood"}'::text[], FALSE)
