INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-14', 'ฉากกั้นห้องกระจกบานเฟี้ยม / บานเลื่อนสลิม (Slim Profile Glass Door)', 'materials-commercial', 'Glass Partition / Architecture', 'แบ่งสัดส่วนห้องครัว ห้องนั่งเล่น หรือห้องทำงานอย่างโปร่งสบายตาด้วยประตูกระจกกรอบอะลูมิเนียมเส้นบางพิเศษ พร้อมกระจกนิรภัย Tempered Glass กันกลิ่นและรักษาความเย็นแอร์', '[{"heading":"1. เฟรมอะลูมิเนียม Slim Profile เส้นบางเฉียบ","body":"ขอบกรอบอะลูมิเนียมสีดำด้านหรือแชมเปญขนาดบางพิเศษ ช่วยให้พื้นที่ดูโปร่งโล่งเหมือนไม่มีผนังกั้น แต่แบ่งฟังก์ชันห้องได้ชัดเจน"},{"heading":"2. กระจกนิรภัย Tempered Glass หนา 8–10 มม.","body":"แข็งแรงกว่ากระจกธรรมดาหลายเท่า เลือกได้ทั้งกระจกใส กระจกชาดำ หรือกระจกลอนแก้ว (Fluted Glass) เพื่อเพิ่มความเป็นส่วนตัว"},{"heading":"3. รางบนไร้ธรณีประตู เดินไม่สะดุด","body":"เลือกติดตั้งแบบรางแขวนด้านบนไม่มีรางพื้น ทำให้เข็นรถเข็น ดูดฝุ่น และเดินผ่านได้ลื่นไหลปลอดภัย"}]'::jsonb, '["เฟรมอะลูมิเนียมสลิมเส้นบางสีดำด้าน","กระจกนิรภัย Tempered Glass (ใส / ลอนแก้ว)","ระบบรางบนไร้ธรณีพื้น ไม่สะดุด"]'::jsonb, '/images/articles/studio-condo.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#กั้นห้องกระจก","#ประตูกระจกบานเลื่อน","#SlimFrame","#Architecture"}'::text[], FALSE)
