INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-15', 'ลิ้นชักซ่อนใต้บันได (Under-Stairs Pull-Out Drawers) เพิ่มพื้นที่เก็บรองเท้าและของใช้', 'condo-space', 'Space Hacker / Smart Storage', 'เปลี่ยนพื้นที่สามเหลี่ยมใต้บันไดที่มักปล่อยว่างให้กลายเป็นลิ้นชักสไลด์รับน้ำหนักสูง สำหรับเก็บรองเท้า อุปกรณ์กีฬา และเครื่องมืออย่างเรียบร้อย', '[{"heading":"1. ออกแบบหน้าบานเฉียงแนบสนิทตามแนวบันได","body":"ทีมช่างวัดองศาความชันจริงหน้างานเพื่อตัดหน้าบานเฉียงให้เข้ามุมพอดี มองจากด้านนอกจะดูเหมือนผนังเรียบหรู"},{"heading":"2. รางสไลด์ Heavy-Duty ดึงออกได้สุดระยะ","body":"ใช้รางลูกปืนรับน้ำหนักสูง 45–60 กก. ทำให้ลิ้นชักขนาดลึกดึงออกมาหยิบของด้านในสุดได้อย่างง่ายดาย"},{"heading":"3. แบ่งโซนเก็บรองเท้า กระเป๋า และของใช้นอกบ้าน","body":"ปรับแต่งช่องภายในเป็นชั้นวางรองเท้า ตะกร้าอุปกรณ์แคมป์ปิ้ง หรือช่องเก็บกล่องเครื่องมือประจำบ้าน"}]'::jsonb, '["วัดมุมชันหน้างานจริง หน้าบานแนบสนิท","รางสไลด์ Heavy-Duty รับน้ำหนักสูง ดึงได้สุด","เปลี่ยนมุมบอดใต้บันไดเป็นตู้เก็บรองเท้าและอุปกรณ์"]'::jsonb, '/images/articles/shoe-cabinet.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ลิ้นชักใต้บันได","#เก็บของใต้บันได","#เปลี่ยนมุมบอด","#SpaceHacker"}'::text[], FALSE)
