INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-16', 'ออกแบบบิ้วอินเพื่อผู้สูงอายุ (Universal Design) ปลอดภัย ใช้งานสะดวกทุกวัย', 'brand-safety', 'Safety & Aging Society', 'ออกแบบเฟอร์นิเจอร์บิ้วอินตามหลัก Universal Design เพื่อความปลอดภัยและความสะดวกสบายของทุกคนในครอบครัว ทั้งขอบมน ไฟเซ็นเซอร์ และชั้นดึงลงได้', '[{"heading":"1. ลบมุมขอบมนและเลือกมือจับเปิดง่าย","body":"ลบเหลี่ยมมุมโต๊ะและขอบตู้ให้โค้งมนลดโอกาสบาดเจ็บหากเกิดการชน พร้อมมือจับทรงโค้งจับถนัดมือไม่ต้องออกแรงบิด"},{"heading":"2. ฟิตติ้งชั้นแขวนดึงลงได้ (Drop-Down Shelf)","body":"ในตู้เสื้อผ้าหรือตู้ครัวบน ติดตั้งราวแขวนและชั้นดึงลงแบบผ่อนแรง ทำให้ผู้สูงอายุหรือผู้ใช้วีลแชร์หยิบของได้โดยไม่ต้องปีนเก้าอี้"},{"heading":"3. ไฟ Motion Sensor นำทางและพื้นไร้ธรณี","body":"ติดตั้งไฟ LED เซ็นเซอร์ตรวจจับความเคลื่อนไหวใต้เตียงและบัวพื้น ช่วยส่องสว่างอัตโนมัติเมื่อลุกเดินตอนกลางคืน"}]'::jsonb, '["ลบมุมขอบมนและมือจับจับถนัดมือ","ราวแขวน/ชั้นวางดึงลงได้ (Drop-down Shelf)","ไฟ Motion Sensor นำทางกลางคืนและพื้นไร้ธรณี"]'::jsonb, '/images/articles/smart-builtin.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#UniversalDesign","#บ้านเพื่อผู้สูงอายุ","#แต่งบ้านปลอดภัย","#AgingSociety"}'::text[], FALSE)
