INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-17', 'ตู้โชว์ฟิกเกอร์และโมเดลสะสม ป้องกันฝุ่น 100% พร้อมไฟสปอตไลต์ขับเน้นดีเทล', 'bedroom-living', 'Hobby & Collector', 'ดูแลของสะสมล้ำค่าด้วยตู้โชว์บิ้วอินกรอบอะลูมิเนียมซีลสักหลาดกันฝุ่น ชั้นกระจกนิรภัยปรับระดับได้ และไฟ LED Spotlight แสงเย็นที่ไม่ทำลายสีโมเดล', '[{"heading":"1. ระบบซีลขอบสักหลาดและกระจกใสตัดแสง","body":"หน้าบานกรอบอะลูมิเนียมสลิมติดตั้งร่องซีลสักหลาดรอบบานช่วยป้องกันฝุ่นละอองเข้าตู้ ลดภาระการปัดฝุ่นชิ้นงานสะสม"},{"heading":"2. ชั้นกระจกนิรภัยปรับระดับความสูงอิสระ","body":"ใช้กระจกใสพิเศษ (Extra Clear Glass) หนา 8 มม. รับน้ำหนัก Statue และโมเดลขนาดใหญ่ได้มั่นคง ปรับระยะชั้นตามสเกลได้"},{"heading":"3. ไฟ LED แสงเย็น ปราศจากรังสี UV และความร้อน","body":"เลือกใช้สปอตไลต์ LED ค่า CRI สูง >90 ที่ขับสีสันของโมเดลได้สมจริงโดยไม่ปล่อยความร้อนสะสมหรือรังสี UV"}]'::jsonb, '["หน้าบานกรอบอะลูมิเนียมซีลขอบกันฝุ่น","ชั้นกระจกนิรภัยใสพิเศษปรับระดับได้","ไฟ LED CRI>90 แสงเย็นไม่ทำลายสีฟิกเกอร์"]'::jsonb, '/images/articles/theater-collector.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ตู้โชว์โมเดล","#ตู้โชว์ฟิกเกอร์","#แต่งห้องของสะสม","#CollectorDisplay"}'::text[], FALSE)
