INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-18', 'โทนสีห้องนอนเพื่อการนอนหลับลึก (Deep Sleep Bedroom Palette)', 'bedroom-living', 'Color Psychology / Wellness', 'เลือกเฉดสีหน้าบานบิ้วอินและวัสดุตกแต่งตามหลักจิตวิทยาสี ด้วยโทนเขียวเสจ (Sage Green) เทาอบอุ่น (Warm Grey) และลายไม้ธรรมชาติ เพื่อช่วยผ่อนคลายสมองก่อนนอน', '[{"heading":"1. เขียวเสจ (Sage Green) ลดความตึงเครียดทางสายตา","body":"สีเขียวอมเทาแบบธรรมชาติให้ความรู้สึกสงบเย็นสบายตา ช่วยลดอัตราความเหนื่อยล้าหลังจ้องหน้าจอตลอดทั้งวัน"},{"heading":"2. เทาอบอุ่น (Warm Grey) และลายไม้โอ๊คธรรมชาติ","body":"ใช้โทน Warm Grey คู่กับลายไม้โอ๊คอ่อนที่มีสัมผัสแบบ Matte เพื่อลดแสงสะท้อนและสร้างความอบอุ่นที่สมดุล"},{"heading":"3. แสงไฟส่องสว่าง 2700K เพื่อการหลับลึก","body":"หลีกเลี่ยงไฟสีขาวจ้าในช่วงค่ำ เลือกใช้ไฟหลืบ 2700K–3000K แบบหรี่แสงได้ ช่วยกระตุ้นการพักผ่อนตามธรรมชาติ"}]'::jsonb, '["หน้าบานสี Matte Sage Green ลดแสงสะท้อน","จับคู่ Warm Grey กับลายไม้โอ๊คธรรมชาติ","ไฟหลืบ 2700K–3000K ปรับหรี่แสงได้ก่อนนอน"]'::jsonb, '/images/articles/headboard-wall.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#แต่งห้องนอนผ่อนคลาย","#DeepSleep","#สีแต่งบ้าน","#ColorPsychology"}'::text[], FALSE)
