INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-19', 'เกาะกลางครัวพร้อมเตาปรุงอาหาร (Cooktop Island) พร้อมระบบฮูดดูดควันแบบสลิม', 'kitchen-bar', 'Kitchen Trend / Cooking Island', 'เปลี่ยนการทำอาหารให้เป็นช่วงเวลาแห่งความสุขร่วมกับครอบครัว ด้วย Kitchen Island ติดตั้งเตาอินดักชันและเครื่องดูดควันแบบดูดลงล่าง (Downdraft) หรือฮูดสลิมดีไซน์โปร่ง', '[{"heading":"1. ทำอาหารไป คุยกับคนในบ้านไปได้","body":"การวางเตาปรุงอาหารบนเกาะกลาง (Island) ทำให้เชฟหันหน้าเข้าหาโต๊ะอาหารและห้องนั่งเล่น ไม่ต้องยืนหันหลังชนผนังอีกต่อไป"},{"heading":"2. ฮูดดูดควันแบบสลิมหรือ Downdraft Hood","body":"หากไม่ต้องการให้ปล่องดูดควันขนาดใหญ่บดบังสายตา สามารถเลือกใช้ฮูดสลิมมินิมอล หรือ Downdraft ที่ฝังซ่อนในท็อปเคาน์เตอร์และเลื่อนขึ้นเมื่อใช้งาน"},{"heading":"3. เผื่อพื้นที่เตรียมอาหารและกันกระเด็นรอบเตา","body":"ควรออกแบบ Island กว้างอย่างน้อย 90–100 ซม. เพื่อเว้นระยะหลังเตาให้ปลอดภัยจากไอร้อนและคราบน้ำมัน"}]'::jsonb, '["เตาอินดักชันฝังบน Island หันหน้าคุยกับครอบครัว","รองรับฮูดสลิมมินิมอลหรือ Downdraft Hood","ความลึก Island 90–100 ซม. ปลอดภัยและใช้งานถนัด"]'::jsonb, '/images/articles/kitchen-ergonomic.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#เตาเกาะกลาง","#CooktopIsland","#ครัวโมเดิร์น","#KitchenTrend"}'::text[], FALSE)
