INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-20', 'ข้อดีของการมีช่างประจำและโรงงานผลิตเอง: ทำไมงาน iKamm ถึงส่งมอบตรงเวลา?', 'brand-safety', 'Brand Strength / Reliability', 'เจาะลึกเบื้องหลังมาตรฐานการผลิตของ iKamm Home Decor ที่มีโรงงาน CNC และทีมช่างประจำของตัวเอง ควบคุมคุณภาพทุกชิ้นส่วนและส่งมอบงานตรงเวลา 100%', '[{"heading":"1. ผลิตจากโรงงานตัวเอง ไม่ต้องรอคิวโรงงานนอก","body":"ชิ้นส่วนไม้ทุกแผ่นผ่านการตัด ปิดขอบ และเจาะร่องด้วยเครื่องจักร CNC มาตรฐานโรงงาน ลดงานตัดฝุ่นหน้างานและควบคุมความแม่นยำระดับมิลลิเมตร"},{"heading":"2. ทีมช่างประจำ ไม่ส่งต่องานให้ซับคอนแทร็กเตอร์","body":"ทีมติดตั้งเป็นพนักงานประจำที่ผ่านการอบรมมาตรฐานเดียวกัน ทำงานสะอาด เก็บรายละเอียดเรียบร้อย และไม่ทิ้งงานกลางคัน"},{"heading":"3. ระบบแพ็กเกจจิ้งและตารางไทม์ไลน์ชัดเจน","body":"วางแผนคิวผลิตและติดตั้งล่วงหน้าเป็นระบบ ลูกค้าทราบกำหนดวันส่งมอบชัดเจนตั้งแต่วันเซ็นสัญญา"}]'::jsonb, '["โรงงานผลิต CNC ของตัวเอง คุมคุณภาพแม่นยำ","ทีมช่างประจำมืออาชีพ ไม่ส่งต่อซับคอนแทร็กเตอร์","วางไทม์ไลน์ชัดเจน ส่งมอบงานตรงเวลา"]'::jsonb, '/images/articles/commercial-reception.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#บิ้วอินส่งมอบตรงเวลา","#โรงงานบิ้วอิน","#ไม่ทิ้งงาน","#iKammStandard"}'::text[], FALSE)
