INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-21', 'ตู้เก็บอุปกรณ์ทำความสะอาด (Broom & Cleaning Cabinet) บ้านเป็นระเบียบอย่างแท้จริง', 'condo-space', 'Home Organization / Utility', 'ซ่อนไม้กวาด ไม้ถูพื้น น้ำยาทำความสะอาด และเครื่องดูดฝุ่นไร้สายไว้ในตู้บิ้วอินหน้ากว้างเพียง 40–50 ซม. พร้อมปลั๊กไฟชาร์จแบตเตอรี่ในตัว', '[{"heading":"1. ใช้พื้นที่แคบ 40–50 ซม. ข้างตู้เย็นหรือโถงทางเดิน","body":"ไม่จำเป็นต้องใช้พื้นที่เยอะ เพียงมุมแคบหน้ากว้าง 40–50 ซม. ก็สามารถทำตู้สูงเก็บอุปกรณ์ทำความสะอาดได้ทั้งบ้าน"},{"heading":"2. ราวแขวนด้ามยาวและชั้นวางน้ำยาเป็นสัดส่วน","body":"ติดคลิปหนีบด้ามไม้กวาด-ไม้ถูพื้นด้านข้าง และแบ่งชั้นครึ่งซีกด้านหนึ่งไว้เก็บถุงขยะ น้ำยาถูพื้น และผ้าไมโครไฟเบอร์"},{"heading":"3. เดินปลั๊กไฟไว้ในตู้สำหรับชาร์จเครื่องดูดฝุ่นไร้สาย","body":"ติดตั้งเต้ารับภายในตู้เพื่อเสียบแท่นชาร์จ Stick Vacuum ให้พร้อมใช้งานตลอดเวลาโดยไม่เกะกะสายตา"}]'::jsonb, '["หน้ากว้าง 40–50 ซม. ใช้มุมแคบได้อย่างคุ้มค่า","ราวแขวนไม้กวาด-ไม้ถูพื้นและช่องเก็บน้ำยา","ปลั๊กไฟภายในตู้สำหรับชาร์จเครื่องดูดฝุ่นไร้สาย"]'::jsonb, '/images/articles/wardrobe-doors.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ตู้เก็บไม้กวาด","#จัดระเบียบบ้าน","#แม่บ้านชอบสิ่งนี้","#UtilityCabinet"}'::text[], FALSE)
