INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-22', 'กระจกเงาติดไฟปรับระดับแสง (Smart LED Mirror) ไอเทมที่ห้องน้ำและห้องแต่งตัวต้องมี', 'smart-tech', 'Bathroom & Dressing / Smart Product', 'ยกระดับห้องน้ำและมุมแต่งตัวด้วยกระจกอัจฉริยะระบบสัมผัส พร้อมแผ่นทำความร้อน Defogger ไล่ฝ้าอัตโนมัติและไฟ LED ปรับอุณหภูมิสีได้', '[{"heading":"1. ระบบ Defogger ไล่ฝ้าหมอกหลังอาบน้ำอุ่น","body":"เพียงแตะปุ่มสัมผัส แผ่นทำความร้อนด้านหลังกระจกจะช่วยสลายไอน้ำที่เกาะบนผิวกระจกให้กลับมาใสกิ๊งภายในไม่กี่วินาที"},{"heading":"2. ปรับแสงได้ 3 โทนสี (Warm / Cool / Daylight)","body":"เลือกแสง Daylight สำหรับการแต่งหน้าให้สีไม่เพี้ยน หรือเปลี่ยนเป็น Warm White เพื่อสร้างบรรยากาศผ่อนคลายยามค่ำ"},{"heading":"3. สั่งตัดรูปทรงและขนาดเข้าชุดกับเคาน์เตอร์","body":"รองรับทั้งทรงสี่เหลี่ยม ทรงกลม และทรงแคปซูล พร้อมไฟซ่อนหลังกระจก (Backlit) กันชื้นมาตรฐานห้องน้ำ"}]'::jsonb, '["ระบบ Defogger ไล่ฝ้าอัตโนมัติหลังอาบน้ำ","ปุ่มสัมผัสปรับหรี่แสงและ 3 โทนสีไฟ LED","สั่งตัดขนาดและรูปทรงเข้าชุดกับเคาน์เตอร์"]'::jsonb, '/images/articles/smart-mirror.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#กระจกไฟLED","#กระจกไล่ฝ้า","#แต่งห้องน้ำ","#SmartMirror"}'::text[], FALSE)
