INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-23', 'บิ้วอินห้องดูหนัง / Home Theater อะคูสติกดีไซน์และซ่อนตู้ลำโพงเนียนตา', 'bedroom-living', 'Entertainment Room / Acoustic', 'เนรมิตโรงภาพยนตร์ส่วนตัวในบ้านด้วยผนัง Acoustic Panels ลดเสียงสะท้อน ตู้ซ่อนลำโพงและเครื่องเสียงแบบระบายอากาศดี พร้อมคุมโทน Dark Mode ลดแสงรบกวน', '[{"heading":"1. ผนังกรุซับเสียง (Acoustic Wall Panels) ลดเสียงก้อง","body":"ใช้แผ่น Acoustic ใยโพลีเอสเตอร์ผสมระแนงไม้ช่วยดูดซับเสียงสะท้อน ทำให้เสียงสนทนาและซาวด์เอฟเฟกต์คมชัดมีมิติ"},{"heading":"2. ซ่อนลำโพง Surround และชุด AVR อย่างเป็นระเบียบ","body":"ออกแบบหน้าบานตะแกรงโปร่งเสียงหรือผ้าอะคูสติกเพื่อซ่อนลำโพงและซับวูฟเฟอร์ พร้อมช่องระบายความร้อนสำหรับเครื่องขยายเสียง"},{"heading":"3. คุมโทนสี Dark Mode และไฟหลืบสลัว","body":"เลือกหน้าบานสีดำด้าน วอลนัทเข้ม และไฟหลืบปรับหรี่แสง เพื่อไม่ให้เกิดแสงสะท้อนรบกวนสายตาระหว่างชมภาพยนตร์"}]'::jsonb, '["ผนัง Acoustic Panels ลดเสียงก้องสะท้อน","ซ่อนลำโพงและ AVR หลังหน้าบานโปร่งเสียง","โทน Dark Mode ลดแสงสะท้อนบนจอภาพ"]'::jsonb, '/images/articles/theater-collector.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#HomeTheater","#ห้องดูหนังในบ้าน","#ผนังซับเสียง","#AcousticDesign"}'::text[], FALSE)
