INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-24', 'ตู้บิวท์อินสองฟังก์ชัน (Dual-Function Furniture) คุ้มค่าพื้นที่เป็น 2 เท่า', 'condo-space', 'Space Optimization / Multi-Function', 'ใช้ประโยชน์จากตู้กั้นห้องเพียง 1 ชุดให้ทำหน้าที่ได้ทั้ง 2 ฝั่ง ฝั่งทางเข้าเป็นตู้รองเท้าพร้อมม้านั่งใส่รองเท้า ส่วนอีกฝั่งเป็นผนังแขวนทีวีลายหินอ่อน', '[{"heading":"1. กั้นโซนพื้นที่แบบไม่ต้องก่อผนังอิฐ","body":"เหมาะสำหรับบ้านหรือคอนโดแบบ Open Plan ที่ต้องการแยกโซนโถงทางเข้าออกจากห้องนั่งเล่นอย่างเป็นสัดส่วน"},{"heading":"2. ฝั่งหน้า: ตู้รองเท้าและม้านั่งเปลี่ยนรองเท้า","body":"ด้านที่หันเข้าหาประตูบ้านจัดเต็มช่องเก็บรองเท้า ตะขอแขวนกุญแจ และม้านั่งบุเบาะสำหรับนั่งใส่รองเท้าสบายๆ"},{"heading":"3. ฝั่งหลัง: ผนังตกแต่งทีวีซ่อนสายไฟ 100%","body":"ด้านที่หันเข้าห้องนั่งเล่นกรุลามิเนตลายหินอ่อนหรือไม้ระแนง พร้อมท่อร้อยสายไฟทีวีซ่อนในโครงสร้างตู้"}]'::jsonb, '["ตู้ 1 ชุด ใช้งานได้ครบทั้ง 2 ด้าน","ฝั่งทางเข้า: ตู้รองเท้า + ม้านั่งใส่รองเท้า","ฝั่งห้องนั่งเล่น: ผนังทีวีซ่อนสายไฟเรียบร้อย"]'::jsonb, '/images/articles/studio-condo.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#เฟอร์นิเจอร์สองฟังก์ชัน","#ตู้กั้นห้อง","#DualFunction","#SpaceSaving"}'::text[], FALSE)
