INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-25', 'มาตรฐานความปลอดภัยในห้องครัว: เลือกระบบกันตกและบานเปิดมุมกว้าง', 'kitchen-bar', 'Safety & Kitchen Details', 'รายละเอียดฟิตติ้งสำคัญที่ช่วยให้ห้องครัวปลอดภัยและใช้งานลื่นไหล ด้วยบานพับเปิดกว้าง 155–170 องศา และราวกันตกข้างลิ้นชัก (Side Railing) สำหรับขวดเครื่องปรุง', '[{"heading":"1. บานพับเปิดมุมกว้าง 155–170 องศา ลดอุบัติเหตุชนขอบบาน","body":"บานพับทั่วไปเปิดได้เพียง 90–105 องศาซึ่งอาจกีดขวางขณะทำครัว บานพับมุมกว้างช่วยให้เปิดบานพับหลบพ้นแนวตัวได้เต็มที่"},{"heading":"2. ราวกันตก Side Railing ในลิ้นชักสูง","body":"สำหรับลิ้นชักเก็บขวดซอส น้ำมัน หรือขวดแก้ว การเสริมราวกันตกด้านข้างและแท่งกั้นแบ่งช่องช่วยป้องกันขวดล้มแตกเมื่อดึงลิ้นชักเร็ว"},{"heading":"3. ระบบ Soft-Close และหน้าบานเข้ามุม","body":"ทุกบานพับและรางลิ้นชักติดตั้งโช้กปิดนุ่มนวล ป้องกันเสียงกระแทกและลดความเสี่ยงนิ้วมือถูกหนีบ"}]'::jsonb, '["บานพับมุมกว้าง 155–170 องศา ไม่ชนศีรษะ","ราวกันตก Side Railing ป้องกันขวดเครื่องปรุงล้ม","ระบบ Soft-Close มาตรฐานยุโรปปิดนุ่มนวล"]'::jsonb, '/images/articles/kitchen-ergonomic.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#ครัวปลอดภัย","#ฟิตติ้งมาตรฐานยุโรป","#ครัวบิ้วอิน","#SafetyFirst"}'::text[], FALSE)
