INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-26', 'เปลี่ยนระเบียงคอนโด ให้เป็นมุมจิบชาและสวนแนวตั้งพักผ่อน', 'bedroom-living', 'Balcony & Relaxation', 'คืนชีวิตชีวาให้ระเบียงคอนโดด้วยม้านั่งบิ้วอินกันน้ำ 100% ปูพื้นไม้เทียม WPC ทนแดดทนฝน และผนังระแนงแขวนสวนแนวตั้งสร้างมุมพักผ่อนส่วนตัว', '[{"heading":"1. ม้านั่งบิ้วอินเก็บของโครงสร้างกันน้ำ 100%","body":"ใช้พลาสวูดหรือโครงอะลูมิเนียมปิดผิวลามิเนต Outdoor ทำม้านั่งยาวพร้อมช่องเปิดเก็บของด้านใต้สำหรับอุปกรณ์ทำสวนและรองเท้า"},{"heading":"2. พื้นไม้เทียม WPC ทนแดด ทนฝน ไม่ลื่น","body":"ปูพื้นระเบียงด้วยแผ่นพื้น WPC แบบระบายน้ำง่าย ช่วยเปลี่ยนพื้นกระเบื้องเย็นๆ ให้ดูอบอุ่นน่าเดินเท้าเปล่า"},{"heading":"3. ผนังระแนงสวนแนวตั้งและไฟ Outdoor","body":"ติดตั้งผนังระแนงไม้เทียมสำหรับแขวนกระถางต้นไม้ฟอกอากาศ พร้อมไฟวอร์มกันน้ำ (IP65) สร้างมุมจิบชาหรือกาแฟยามเช้า"}]'::jsonb, '["ม้านั่งบิ้วอินกันน้ำ 100% พร้อมช่องเก็บของ","พื้นไม้เทียม WPC ทนแดดฝนและระบายน้ำได้ดี","ผนังระแนงสวนแนวตั้งพร้อมไฟกันน้ำ IP65"]'::jsonb, '/images/articles/balcony-lounge.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#แต่งระเบียงคอนโด","#มุมจิบชานอกบ้าน","#สวนแนวตั้ง","#BalconyDesign"}'::text[], FALSE)
