INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-27', 'โต๊ะรีดผ้าแบบพับซ่อนในลิ้นชัก (Built-in Ironing Board) รีดเสร็จพับเก็บใน 3 วิ', 'condo-space', 'Smart Storage / Laundry Hack', 'ประหยัดพื้นที่ห้องแต่งตัวด้วยอุปกรณ์โต๊ะรีดผ้าพับซ่อนในช่องลิ้นชักตู้เสื้อผ้า ดึงออกมากางใช้งานและหมุนปรับมุมได้ 180 องศา รีดเสร็จพับเก็บได้ทันที', '[{"heading":"1. ซ่อนในช่องลิ้นชักขนาดมาตรฐาน","body":"ติดตั้งชุดรางโต๊ะรีดผ้าในช่องลิ้นชักความกว้าง 40–50 ซม. ลึก 50 ซม. ของตู้เสื้อผ้าหรือตู้ซักล้างโดยไม่เสียพื้นที่แขวนผ้า"},{"heading":"2. กางออกพร้อมระบบหมุนปรับมุม 180 องศา","body":"ดึงลิ้นชักออกแล้วพลิกแผ่นรองรีดขึ้นมาล็อกอัตโนมัติ หมุนปรับทิศทางได้ 180 องศาตามความถนัดของผู้ใช้งาน"},{"heading":"3. ผ้าคลุมทนความร้อน ถอดซักได้","body":"มาพร้อมเบาะรองรีดทนความร้อนสูง ถอดซักทำความสะอาดได้ และพับเก็บเข้าตู้เรียบร้อยภายใน 3 วินาที"}]'::jsonb, '["ซ่อนแนบเนียนในช่องลิ้นชักตู้เสื้อผ้า","หมุนปรับมุมได้ 180 องศา ใช้งานถนัดมือ","พับเก็บคืนในตู้ภายใน 3 วินาที ไม่เกะกะห้อง"]'::jsonb, '/images/articles/power-track.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#โต๊ะรีดผ้าพับเก็บได้","#SmartStorage","#ตู้เสื้อผ้าอเนกประสงค์","#LaundryHack"}'::text[], FALSE)
