INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-28', 'รีวิวลูกค้าจริง: จากห้องโล่งๆ สู่บ้านในฝันที่ใช้งานได้จริงทุกตารางเมตร', 'brand-safety', 'Customer Review & Testimonial', 'ความประทับใจจากครอบครัวลูกค้าบ้านเดี่ยว 4 ห้องนอน ที่ไว้วางใจให้ iKamm Home Decor ดูแลงานบิ้วอินทั้งหลัง ตั้งแต่ขึ้นแบบ 3D จนถึงวันส่งมอบงานตรงเวลา', '[{"heading":"1. ออกแบบ 3D เสมือนจริงและปรับแก้จนตรงใจ","body":"ทีมดีไซเนอร์ร่วมวางผังทุกโซนตั้งแต่โถงรับแขก ครัว ห้องนอนหลัก 4 ห้อง และ Walk-in Closet พร้อมภาพ 3D เพื่อเห็นแสงเงาและสัดส่วนจริงก่อนผลิต"},{"heading":"2. ติดตั้งสะอาด เก็บงานซิลิโคนและขอบบัวละเอียด","body":"ลูกค้าชื่นชมความเรียบร้อยของทีมช่างประจำที่ป้องกันพื้นก่อนเข้างาน เก็บฝุ่นทุกวัน และเก็บงานรอยต่อระหว่างตู้กับผนังได้เนียนกริบ"},{"heading":"3. ส่งมอบตรงตามกำหนดและใช้งานได้จริงทุกจุด","body":"ครอบครัวสามารถย้ายเข้าอยู่ได้ตามฤกษ์ที่วางไว้ พร้อมฟังก์ชันตู้เก็บของที่รองรับไลฟ์สไตล์สมาชิกทุกคน"}]'::jsonb, '["ภาพ 3D เสมือนจริงตรงปกกับงานติดตั้งจริง","ช่างทำงานสะอาด เก็บงานละเอียดครบ 4 ห้องนอน","ส่งมอบตรงตามกำหนดเวลาที่ลูกค้าวางแผนไว้"]'::jsonb, '/images/articles/headboard-wall.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#รีวิวบิ้วอิน","#ลูกค้าประทับใจ","#งานบิ้วอินคุณภาพ","#ClientReview"}'::text[], FALSE)
