INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-29', 'ทำไมการเลือกบริษัทที่มีสาขาทั้งในไทยและต่างประเทศถึงสร้างความมั่นใจได้มากกว่า?', 'brand-safety', 'Brand Reputation & International Standard', 'รู้จักศักยภาพของ iKamm Home Decor ที่ให้บริการทั้งในประเทศไทย (กรุงเทพฯ) และต่างประเทศ (มะนิลา ฟิลิปปินส์) ภายใต้มาตรฐานการออกแบบและการผลิตระดับสากลเดียวกัน', '[{"heading":"1. เครือข่ายสาขาทั้งกรุงเทพฯ และมะนิลา","body":"การขยายธุรกิจสู่ต่างประเทศสะท้อนถึงความมั่นคงทางการเงิน ระบบบริหารจัดการที่แข็งแกร่ง และความไว้วางใจจากลูกค้าในระดับภูมิภาค"},{"heading":"2. มาตรฐานการออกแบบและซัพพลายเชนระดับสากล","body":"ทุกโปรเจกต์ใช้วัสดุ ฟิตติ้ง และมาตรฐาน QC เดียวกันทั้งในไทยและต่างประเทศ มั่นใจได้ในคุณภาพที่สม่ำเสมอ"},{"heading":"3. ทีมบริการลูกค้า 3 ภาษา (ไทย-อังกฤษ-จีน) และบริการหลังการขาย","body":"สื่อสารสะดวกครบทุกภาษา มีตัวตนชัดเจน ติดตามงานและดูแลหลังการขายได้ตลอดอายุการใช้งาน"}]'::jsonb, '["สาขากรุงเทพฯ (ประเทศไทย) และมะนิลา (ฟิลิปปินส์)","มาตรฐาน QC และสายการผลิตระดับสากลเดียวกัน","ทีมงานสื่อสารได้ทั้งไทย อังกฤษ จีน พร้อมดูแลหลังการขาย"]'::jsonb, '/images/articles/commercial-reception.jpg', NULL, 'อ่าน 4 นาที', '{"#ikammhome","#iKammHomeDecor","#มาตรฐานระดับสากล","#ตกแต่งภายในมืออาชีพ","#InternationalStandard"}'::text[], FALSE)
