INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('ikamm-day-30', 'พร้อมเปลี่ยนบ้านของคุณให้เป็นพื้นที่ที่น่าอยู่ที่สุดแล้วหรือยัง?', 'brand-safety', 'Final Call to Action', 'เริ่มต้นสร้างบ้านในฝันกับ บริษัท อิคัม โฮม เดคคอร์ จำกัด รับบริการให้คำปรึกษา ออกแบบภาพ 3D วัดพื้นที่หน้างานด้วยเลเซอร์ และประเมินราคาฟรี', '[{"heading":"ขั้นตอนที่ 1: ส่งแปลนหรือนัดวัดพื้นที่หน้างานฟรี","body":"ทีมงานเข้าวัดขนาดจริงด้วยเครื่องมือเลเซอร์ที่แม่นยำ เพื่อเก็บรายละเอียดเสา คาน และจุดปลั๊กไฟครบถ้วน"},{"heading":"ขั้นตอนที่ 2: ออกแบบ 3D และคัดเลือกวัสดุจริง","body":"ร่วมเลือกโทนสีลามิเนต คิ้วสแตนเลส ท็อปหิน และฟิตติ้งที่ตรงกับงบประมาณและสไตล์บ้านของคุณ"},{"heading":"ขั้นตอนที่ 3: ผลิตในโรงงานและติดตั้งส่งมอบตรงเวลา","body":"ควบคุมคุณภาพทุกขั้นตอนโดยโรงงานและทีมช่างประจำของ iKamm พร้อมรับประกันงานติดตั้งอย่างมั่นใจ"}]'::jsonb, '["ปรึกษาและออกแบบภาพ 3D เสมือนจริง","บริการวัดพื้นที่หน้างานและประเมินราคาฟรี","ดูแลครบวงจรทั้งคอนโด บ้านเดี่ยว และงานพาณิชย์"]'::jsonb, '/images/articles/smart-builtin.jpg', NULL, 'อ่าน 3 นาที', '{"#ikammhome","#เพราะบ้านสะท้อนตัวตนของคุณ","#iKammHome","#นัดประเมินพื้นที่ฟรี","#3DDesign"}'::text[], FALSE)
