INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('rebar-standards', 'เหล็กเส้นกลม (RB) และเหล็กข้ออ้อย (DB) มาตรฐาน มอก. เลือกใช้ยังไงไม่ให้ผิดสเปก', 'structure', 'เหล็กเสริม', 'ทำความรู้จักความแตกต่างระหว่างเหล็กเส้นกลม SR24 กับเหล็กข้ออ้อย SD30/SD40/SD50 พร้อมหน้าที่ในโครงสร้างคอนกรีตเสริมเหล็กและวิธีเช็กมาตรฐาน มอก.', '[{"heading":"เหล็กเส้นกลม (Round Bar : RB) — มาตรฐาน มอก. 20-2543","body":"มีผิวเรียบกลม นิยมใช้ชั้นคุณภาพ SR24 โดยขนาด 6 มม. และ 9 มม. มักนำไปดัดเป็น \"เหล็กปลอก\" เพื่อรัดโครงเหล็กแกนในงานเสาและคาน ช่วยรับแรงเฉือนและยึดเหล็กหลักให้อยู่ในตำแหน่งที่ถูกต้อง"},{"heading":"เหล็กข้ออ้อย (Deformed Bar : DB) — มาตรฐาน มอก. 24-2559","body":"มีบั้งนูนเป็นระยะสม่ำเสมอตลอดเส้น เพื่อเพิ่มแรงยึดเกาะระหว่างเหล็กกับเนื้อคอนกรีต มีหลายชั้นคุณภาพ เช่น SD30, SD40 และ SD50 ใช้เป็นเหล็กแกนหลักในการรับแรงดึงของฐานราก ตอม่อ เสา และคานโครงสร้าง"},{"heading":"ข้อควรระวังในการตรวจรับเหล็กหน้างาน","body":"ควรตรวจสอบตราประทับ มอก. และรหัสชั้นคุณภาพที่ตัวเหล็กเส้น (เช่น SR24, SD40) รวมถึงขนาดเส้นผ่านศูนย์กลางให้ตรงตามแบบวิศวกรรม และระวังเหล็กที่ขึ้นสนิมขุมลึกจนกัดกร่อนเนื้อเหล็ก"}]'::jsonb, '["งานเหล็กปลอกเสา-คาน และงานดัดงอทั่วไป: เหล็กเส้นกลม RB6 หรือ RB9 เกรด SR24","งานเหล็กแกนเสา คาน ฐานรากบ้านและอาคาร: เหล็กข้ออ้อย DB12, DB16, DB20 เกรด SD40 ตามรายการคำนวณวิศวกร"]'::jsonb, NULL, NULL, 'อ่าน 4 นาที', '{}'::text[], FALSE)
