INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('foundation-basics', 'ลำดับงานโครงสร้างพื้นฐาน: จากฐานราก ตอม่อ ถึงคานคอดิน', 'structure', 'งานโครงสร้าง', 'เข้าใจหัวใจของความมั่นคงตัวบ้าน ตั้งแต่การเตรียมดิน เทคอนกรีตหยาบ วางลูกปูนหนุนเหล็ก ไปจนถึงการบ่มคอนกรีตให้ได้กำลังอัดเต็มตามออกแบบ', '[{"heading":"1. งานขุดดินและเทคอนกรีตหยาบ (Lean Concrete)","body":"หลังขุดหลุมฐานรากหรือตัดหัวเสาเข็มแล้ว ควรเทคอนกรีตหยาบปรับระดับก้นหลุมก่อนวางตะแกรงเหล็กฐานราก เพื่อป้องกันความชื้นและสิ่งสกปรกจากดินปนเปื้อนเข้าสู่เนื้อคอนกรีตโครงสร้าง"},{"heading":"2. การหนุนลูกปูน (Covering) และผูกเหล็ก","body":"เหล็กเสริมต้องไม่วางติดดินหรือชิดไม้แบบโดยตรง ต้องใช้ลูกปูนหนุนให้มีระยะหุ้มคอนกรีตตามแบบ เพื่อป้องกันความชื้นซึมเข้าไปทำให้เหล็กเป็นสนิมและดันคอนกรีตแตกในอนาคต"},{"heading":"3. การเทและบ่มคอนกรีต","body":"ใช้ปูนซีเมนต์ปอร์ตแลนด์ ประเภท 1 (หรือประเภท 2/5 หากดินเค็มหรือน้ำใต้ดินมีซัลเฟตสูง) ระหว่างเทควรจี้คอนกรีตด้วยเครื่องจี้เขย่าเพื่อไล่ฟองอากาศ ลดปัญหาโพรง (Honeycomb) และบ่มชื้นต่อเนื่องหลังเทอย่างน้อย 7 วัน"}]'::jsonb, '["คอนกรีตโครงสร้างฐานราก-คาน: ใช้ปูนซีเมนต์ปอร์ตแลนด์ ประเภท 1 หรือคอนกรีตผสมเสร็จกำลังอัดตามแบบวิศวกร","อุปกรณ์เสริมจำเป็น: ลูกปูนหนุนเหล็ก (Spacer) ตามระยะหุ้มที่กำหนดในแบบ"]'::jsonb, NULL, NULL, 'อ่าน 5 นาที', '{}'::text[], FALSE)
