INSERT INTO public.articles (id, title, category_id, category_name, summary, sections, recommendations, image, post_url, read_time, hashtags, is_fb_highlight)
VALUES ('plastering-checklist', 'เช็กลิสต์ตรวจรับงานก่อฉาบและเตรียมผิวก่อนทาสีบ้าน', 'structure', 'งานผนัง & อิฐ', 'วิธีตรวจเช็กผนังก่อฉาบด้วยตนเองก่อนส่งมอบงวดงาน ตั้งแต่การเคาะฟังเสียงโพรง การเช็กดิ่ง-ฉาก ไปจนถึงการบ่มผนังฉาบเพื่อลดรอยแตกลายงา', '[{"heading":"1. เช็กแนวผนัง ดิ่ง และความเรียบด้วยสามเหลี่ยมปาดปูน","body":"ใช้ไม้สามเหลี่ยมหรือระดับน้ำทาบแนบผนังทั้งแนวตั้งและแนวนอน ไม่ควรมีช่องแสงลอดใต้ไม้เกินมาตรฐาน (โดยทั่วไปไม่เกิน 2–3 มม.) และมุมเสา-มุมหน้าต่างควรได้ฉากเรียบร้อย"},{"heading":"2. เคาะฟังเสียงโปร่ง (ปูนร่อน)","body":"ใช้ด้ามไขควงหรือไม้เคาะเบาๆ ให้ทั่วผนัง หากได้ยินเสียงก้องโปร่ง แสดงว่าปูนฉาบไม่ยึดเกาะกับอิฐ ควรให้ช่างสกัดซ่อมก่อนทาสี มิฉะนั้นสีจะพองลอกในภายหลัง"},{"heading":"3. การบ่มผนังและการทิ้งระยะก่อนทาสี","body":"หลังฉาบเสร็จควรรดน้ำบ่มผนังอย่างน้อย 3–5 วันเพื่อลดการแตกร้าวจากการหดตัว และรอให้ผนังแห้งสนิท (ค่าความชื้นเหมาะสม) ก่อนลงสีรองพื้นปูนใหม่เพื่อป้องกันสีด่างหรือลอกล่อน"}]'::jsonb, '["งานฉาบอิฐมอญ/อิฐบล็อก: ใช้ปูนซีเมนต์ผสมหรือปูนฉาบสำเร็จรูปทั่วไป","งานฉาบอิฐมวลเบา: ต้องใช้ปูนฉาบสำหรับอิฐมวลเบาโดยเฉพาะ เพื่อการยึดเกาะและลดการแตกร้าว","สีรองพื้น: ใช้สีรองพื้นปูนใหม่กันด่างก่อนทาสีจริงเสมอ"]'::jsonb, NULL, NULL, 'อ่าน 4 นาที', '{}'::text[], FALSE)
